"""One-shot bootstrap: materializes the whole il-media-tracker repo.
Run by .github/workflows/bootstrap.yml, then both files remove themselves."""
import base64, os

FILES = {
    '.github/workflows/digest.yml':
        '',
    '.github/workflows/scan.yml':
        '',
    '.gitignore':
        'ZGF0YS9zdGF0ZS5qc29uCioucHljCl9fcHljYWNoZV9fLwouZW52Cg==',
    'README.md':
        '',
    'config/sources.yaml':
        '',
    'config/targets.yaml':
        '',
    'data/items/.gitkeep':
        '',
    'digests/.gitkeep':
        '',
    'docs/data/.gitkeep':
        '',
    'docs/index.html':
        '',
    'pipeline/__init__.py':
        '',
    'pipeline/alerts.py':
        '',
    'pipeline/common.py':
        '',
    'pipeline/detect.py':
        '',
    'pipeline/digest.py':
        '',
    'pipeline/fetch.py':
        '',
    'pipeline/publish.py':
        '',
    'pipeline/run.py':
        '',
    'pipeline/store.py':
        '',
    'requirements.txt':
        'ZmVlZHBhcnNlcj49Ni4wCnJlcXVlc3RzPj0yLjMxClB5WUFNTD49Ni4wCmJlYXV0aWZ1bHNvdXA0Pj00LjEyCg==',
}

for path, b64 in FILES.items():
    os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
    with open(path, 'wb') as f:
        f.write(base64.b64decode(b64))
print(f'materialized {len(FILES)} files')
